  const ::flatbuffers::Vector<uint32_t> *shape() const {
    return GetPointer<const ::flatbuffers::Vector<uint32_t> *>(VT_SHAPE);
  }
  /// Fixed ordered component names for each sample; determines payload interpretation with
  /// shape/dtype.
  const ::flatbuffers::Vector<::flatbuffers::Offset<::flatbuffers::String>> *components() const {
    return GetPointer<const ::flatbuffers::Vector<::flatbuffers::Offset<::flatbuffers::String>> *>(VT_COMPONENTS);
  }
