  uint32_t payload_offset() const {
    return GetField<uint32_t>(VT_PAYLOAD_OFFSET, 0);
  }
  /// Fixed byte length of this region payload, not the number of samples or words.
  uint32_t payload_bytes() const {
    return GetField<uint32_t>(VT_PAYLOAD_BYTES, 0);
  }
  /// Version of the declared region payload encoding; not a firmware version or runtime ID.
  uint16_t encoding_version() const {
    return GetField<uint16_t>(VT_ENCODING_VERSION, 0);
  }
  /// Row-major (x,y,z,nx,ny,nz), xyz in frame-relative m and unit normals.
  /// Length is 6*product(shape); shape excludes component dimensions. Without
  /// actual physical sample-point mapping, empty with geometry_valid=false.
